--- lib/rust/crates/pathland-core-transport/src/conformance.rs	
+++ lib/rust/crates/pathland-core-transport/src/conformance.rs	
@@ -0,0 +1,65 @@
+//! Golden conformance vectors for the network batch format.
+//!
+//! These byte arrays are the canonical wire representation (see
+//! `spec/CONFORMANCE.md`). A conforming implementation MUST encode and decode
+//! these exactly.
+
+#[cfg(test)]
+mod tests {
+    use crate::batch::{encode_batch, BatchDecoder};
+    use pathland_opcode::{category, Opcode};
+
+    /// The canonical bytes for `NETWORK:BATCH` vector 13 (see CONFORMANCE.md).
+    const VECTOR_13: &[u8] = &[
+        0x4C, 0x50, 0x4C, 0x50, // magic PLPL (LE)
+        0x01, 0x00, // version 1
+        0x00, 0x00, // flags guest->host
+        0x01, 0x00, 0x00, 0x00, // frameCount = 1
+        0x01, 0x00, 0x00, 0x00, // opcodeCount = 1
+        0x01, 0x01, 0x00, 0x00, 0x01, 0x00, 0x00, 0x00, 0x02, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
+        0x00, // CREATE_NODE (id=1, VSTACK)
+        0x06, 0x00, 0x00, 0x00, // arenaDeltaLen = 6
+        0x02, 0x00, 0x00, 0x00, 0x48, 0x69, // arena entry [len=2]["Hi"]
+    ];
+
+    /// The canonical bytes for `NETWORK:BATCH` vector 14 (see CONFORMANCE.md).
+    const VECTOR_14: &[u8] = &[
+        0x4C, 0x50, 0x4C, 0x50, // magic PLPL (LE)
+        0x01, 0x00, // version 1
+        0x00, 0x00, // flags
+        0x02, 0x00, 0x00, 0x00, // frameCount = 2
+        0x00, 0x00, 0x00, 0x00, // opcodeCount = 0
+        0x00, 0x00, 0x00, 0x00, // arenaDeltaLen = 0
+    ];
+
+    #[test]
+    fn vector_13_encode_exactly() {
+        let opcodes = [Opcode::new(category::TREE, 0x01, 0, 1, 0x0002, 0)];
+        let arena_delta = [0x02, 0x00, 0x00, 0x00, 0x48, 0x69];
+        let bytes = encode_batch(1, 0, &opcodes, &arena_delta);
+        assert_eq!(bytes, VECTOR_13);
+    }
+
+    #[test]
+    fn vector_14_encode_exactly() {
+        let bytes = encode_batch(2, 0, &[], &[]);
+        assert_eq!(bytes, VECTOR_14);
+    }
+
+    #[test]
+    fn vectors_decode_and_round_trip() {
+        for bytes in [VECTOR_13, VECTOR_14] {
+            let mut decoder = BatchDecoder::new();
+            let batch = decoder.decode(bytes).unwrap();
+            assert_eq!(batch.flags(), 0);
+            let reencoded = {
+                let opcodes: Vec<Opcode> = batch.opcodes().collect();
+                // The decoder has already mirrored the arena delta; re-encoding
+                // with an empty delta produces a valid follow-up batch.
+                encode_batch(batch.frame_count(), batch.flags(), &opcodes, &[])
+            };
+            // Decoding again (empty delta appended to mirror) must stay valid.
+            let _ = decoder.decode(&reencoded).unwrap();
+        }
+    }
+}

Index: lib/rust/crates/pathland-core-transport/src/lib.rs
===================================================================
--- lib/rust/crates/pathland-core-transport/src/lib.rs	
+++ lib/rust/crates/pathland-core-transport/src/lib.rs	
@@ -0,0 +1,74 @@
+//! # pathland-transport
+//!
+//! How Pathland opcodes are transported from the guest engine to host
+//! renderers. There are two peer backends:
+//!
+//! - **Shared memory** (desktop/native): the ring buffer + arena in
+//!   `pathland-opcode` (`Guest`/`Host`). Zero-copy. This crate treats it as
+//!   the local transport — no duplication.
+//! - **Network batch** (SSR → browser): opcodes + arena data serialized into
+//!   **batches**, flushed on a **time interval** or a **network-frame size**
+//!   (whichever comes first).
+//!
+//! `pathland_opcode::Frame` is the **transport seam**: `pathland-host`'s
+//! `RenderTree::apply_frame` consumes frames regardless of origin. `BatchDecoder`
+//! produces `Frame` views over decoded batches, so a network batch feeds the
+//! renderer exactly like a shared-memory frame.
+//!
+//! ## Batch wire format
+//!
+//! ```text
+//! magic "PLPL" (u32 LE) | version (u16) | flags (u16) | frameCount (u32)
+//! | opcodeCount (u32) | opcodes (16 B × opcodeCount) | arenaDeltaLen (u32)
+//! | arena delta bytes
+//! ```
+//!
+//! The arena is append-only (bump); batches carry only the bytes appended since
+//! the previous batch. The decoder appends them to a mirrored arena, so absolute
+//! `arenaRef` offsets stay valid — exactly as in shared memory.
+//!
+//! ## Example (producer)
+//!
+//! ```no_run
+//! use pathland_transport::{Batcher, BatchPolicy, BatchEncoder};
+//! use std::time::Duration;
+//!
+//! let policy = BatchPolicy::new(Duration::from_millis(4), 1400);
+//! let mut batcher = Batcher::new(policy);
+//! let mut encoder = BatchEncoder::new();
+//!
+//! // batcher.push_frame(&frame) accumulates opcodes + arena delta;
+//! // batcher.flush() -> Option<Vec<u8>> produces the serialized batch.
+//! ```
+
+#![forbid(unsafe_op_in_unsafe_fn)]
+
+extern crate alloc;
+
+mod batch;
+mod batching;
+mod conformance;
+mod net;
+mod ring;
+mod traits;
+
+pub use batch::{encode_batch, Batch, BatchDecoder, BatchEncoder};
+pub use batching::{Batcher, BatchPolicy};
+pub use net::NetBatchEncoder;
+pub use ring::RingTransport;
+pub use traits::{
+    DriverTransport, FrameSource, InputSink, OpcodeBatch, ProtocolError, TransportError,
+};
+
+/// Wire magic for network batches (`PLPL`).
+pub const BATCH_MAGIC: u32 = 0x504C_504C;
+/// Wire version for the batch format.
+pub const BATCH_VERSION: u16 = 1;
+
+/// Direction of a batch. Events are not yet implemented; this bit is reserved.
+pub mod direction {
+    /// The batch carries guest → host tree/style opcodes.
+    pub const GUEST_TO_HOST: u16 = 0x0000;
+    /// The batch carries host → guest raw-input events (reserved).
+    pub const HOST_TO_GUEST: u16 = 0x0001;
+}

