+fn vstack(children: Vec<Node>) -> Node {
+    Node {
+        id: 0,
+        component: Component::VStack,
+        children,
+        properties: BTreeMap::new(),
+        gestures: Vec::new(),
+    }
+}
+
+fn hstack(children: Vec<Node>) -> Node {
+    Node {
+        id: 0,
+        component: Component::HStack,
+        children,
+        properties: BTreeMap::new(),
+        gestures: Vec::new(),
+    }
+}
