-    }
-
-    /// Interpret `B` as an `f32` (bit-preserving).
-    #[inline]
-    pub fn b_f32(&self) -> f32 {
-        f32::from_bits(self.b())
-    }
-
-    /// Interpret `C` as an `f32` (bit-preserving).
-    #[inline]
-    pub fn c_f32(&self) -> f32 {
-        f32::from_bits(self.c())
-    }
