-        let a = u32::from_le_bytes(bytes[4..8].try_into().unwrap());
-        let b = u32::from_le_bytes(bytes[8..12].try_into().unwrap());
-        let c = u32::from_le_bytes(bytes[12..16].try_into().unwrap());
