-/// Drain all pending `EVENT`-category opcodes from the host → guest event ring,
-/// advancing `eventReadCursor`. The guest (app/engine) reads raw inputs here.
-#[inline]
-pub(crate) fn read_events(
-    event_slots: &[u8],
-    header: &mut [u8],
-    mask: usize,
