 impl<'a> SharedHeader<'a> {
     /// Wrap an immutable view of the shared linear memory.
     pub fn new(mem: &'a [u8]) -> Self {
         Self { mem }
     }

     fn u32(&self, off: usize) -> u32 {
         u32::from_le_bytes(self.mem[off..off + 4].try_into().unwrap())
