     let tap_count = count.clone();
     vstack![
         hstack![
             text(format!("Count: {}", *count.borrow()).as_str())
                 .frame(Some(size::FILL), None, None),
             button("Increment").on_tap_gesture(move || *tap_count.borrow_mut() += 1),
