     let emit = {
         let engine = engine.clone();
         let ring = ring.clone();
         let count = count.clone();
         let handlers = handlers.clone();
         move || {
             let mut tree = build_tree(&count);
             assign_ids(&mut tree, &mut 1);
             let mut h = handlers.borrow_mut();
             h.clear();
             pathland_view::collect_tap_handlers(&tree, &mut *h);
