         // Entry 0: len 1 "a"  -> used = [1,0,0,0,'a'] (5 bytes)
         let first = enc.encode(1, &opcodes, &[1u8, 0, 0, 0, b'a']);
         // Append entry 1: len 4 "bcde" -> used = [1,0,0,0,'a', 4,0,0,0,'b','c','d','e'] (13)
         let second = enc.encode(
             2,
             &opcodes,
