         component: Component::Text { text: text.into() },
         children: Vec::new(),
         properties: BTreeMap::new(),
         gestures: Vec::new(),
     }
 }

 fn vstack(children: Vec<Node>) -> Node {
     Node {
         id: 0,
         component: Component::VStack,
         children,
         properties: BTreeMap::new(),
         gestures: Vec::new(),
     }
